from typing import List

def calculate_departures(n: int, k: int, a: List[int]) -> int:
    seat_count = k
    dep_count = 0
    for i in range(n):
        if seat_count >= a[i]:
            seat_count -= a[i]
            if seat_count == 0:
                dep_count += 1
                seat_count = k
        else:
            dep_count += 1
            seat_count = k - a[i]

    if seat_count != k:
        dep_count += 1

    return dep_count
